# -*- coding: utf-8 -*-
import json
from datetime import date, timedelta

TR_AY = {
    "ocak": 1, "şubat": 2, "subat": 2, "mart": 3, "nisan": 4,
    "mayıs": 5, "mayis": 5, "haziran": 6, "temmuz": 7,
    "ağustos": 8, "agustos": 8, "eylül": 9, "eylul": 9,
    "ekim": 10, "kasım": 11, "kasim": 11, "aralık": 12, "aralik": 12,
}

def parse_tutar(v):
    if isinstance(v, bool) or not isinstance(v, (int, float, str)):
        return None
    if isinstance(v, (int, float)):
        f = float(v)
        return f if f == f else None  # NaN kontrolü
    s = v.strip().replace("₺", "").upper().replace("TL", "")
    s = "".join(s.split())
    if not s:
        return None
    try:
        if "," in s and "." in s:
            # hem . hem , : son ayırıcı ondalık olmalı, ötekiler binlik
            last_comma, last_dot = s.rfind(","), s.rfind(".")
            if last_comma < last_dot:  # nokta sondan sonra -> bozuk
                return None
            s = s.replace(".", "").replace(",", ".")
        elif "," in s:
            parts = s.split(",")
            if len(parts) > 2 or (len(parts[1]) != 3 and len(parts[-1]) == 3):
                # çoklu virgül veya "1.234" tarzı tekli ama binlik benzeri -> bozuk kabul et
                return None
            s = s.replace(",", ".")
        elif "." in s:
            parts = s.split(".")
            if len(parts) > 2:
                return None
            last = parts[-1]
            if len(last) == 3 and len(parts) == 2:
                # "1.000" -> binlik; "7.5" -> ondalık (son parça 1-2 rakam)
                s = s.replace(".", "")
            elif len(last) > 3 or not last.isdigit():
                return None
        else:
            if not s.replace("-", "", 0).isdigit() and not all(c in "0123456789" for c in s):
                return None
        f = float(s)
        return f if f == f else None
    except ValueError:
        return None

def parse_tarih(v):
    if not isinstance(v, str):
        return None
    s = v.strip()
    try:
        # G Ay YYYY (Türkçe ay adı)
        parts = s.split(" ")
        if len(parts) == 3 and parts[0].isdigit() and parts[2].isdigit():
            g, ayn, y = int(parts[0]), parts[1].lower(), int(parts[2])
            if ayn in TR_AY:
                return date(y, TR_AY[ayn], g)  # geçersiz tarih ValueError -> None
        for sep in ("-", "/"):
            if sep in s and " " not in s:
                p = s.split(sep)
                if len(p) == 3:
                    y, m, d = (int(x) for x in p)
                    return date(y, m, d)
    except (ValueError, TypeError):
        return None
    return None

def norm_durum(v):
    if not isinstance(v, str):
        return None
    s = v.strip().lower()
    for c, r in (("i", "ı"), ("İ", "I")):  # Türkçe İ/ı normalizasyonu
        s = s.replace(c, r)
    return s

gecerli = {}   # id -> kayıt (son geçerli kazanır)
hatali = 0
with open("siparisler.jsonl", encoding="utf-8") as f:
    for line in f:
        raw = line.rstrip("\n").rstrip("\r")
        if not raw.strip():
            continue
        try:
            obj = json.loads(raw)
        except (json.JSONDecodeError, ValueError):
            hatali += 1
            continue
        ok = False
        if isinstance(obj, dict):
            for k in ("id", "musteri", "tutar", "tarih", "durum"):
                if k not in obj:
                    break
            else:
                m = norm_durum(obj["durum"])
                tutar = parse_tutar(obj["tutar"])
                dt = parse_tarih(obj["tarih"])
                mid = obj["id"]
                mus = obj["musteri"] if isinstance(obj["musteri"], str) else None
                if m is not None and tutar is not None and dt is not None and \
                   mus is not None and isinstance(mid, (int, float)) and not isinstance(mid, bool):
                    ok = True
        if not ok:
            hatali += 1
            continue
        gecerli[mid] = {"musteri": mus.strip(), "tutar": round(tutar, 2),
                        "tarih": dt.isoformat(), "durum": m}

tekil = list(gecerli.values())
iptal_sayisi = sum(1 for r in tekil if r["durum"] == "iptal")
aktif = [r for r in tekil if r["durum"] != "iptal"]
toplam_tutar = round(sum(r["tutar"] for r in aktif), 2)

aylik = {}
for r in aktif:
    anahtar = r["tarih"][:7]
    aylik[anahtar] = round(aylik.get(anahtar, 0.0) + r["tutar"], 2)

mus_toplam = {}
for r in aktif:
    mus_toplam[r["musteri"]] = mus_toplam.get(r["musteri"], 0.0) + r["tutar"]
en_cok_harcayan = max(mus_toplam.items(), key=lambda kv: (kv[1], -list(gecerli.values()).index(...))) if False else None

# en yüksek tutar; eşitlik halinde ilk görülen müşteri
if mus_toplam:
    en_yuksek = max(v for v in mus_toplam.values())
    adaylar = [m for m, t in mus_toplam.items() if abs(t - en_yuksek) < 1e-9]
    en_cok_harcayan = min(gecerli.keys(), key=lambda k: tekil.index(next(r for r in tekil if r["musteri"] == adaylar[0])))  # placeholder, aşağıda düzeltiliyor

# daha basit ve doğru: ilk görülen sırada dolaş
sira = []
for rec in tekil:
    if rec["musteri"] not in sira:
        sira.append(rec["musteri"])
en_yuksek2 = max(mus_toplam.values())
en_cok_harcayan = next(m for m in sira if abs(mus_toplam[m] - en_yuksek2) < 1e-9)

ozet = {
    "gecerli_kayit": len(tekil),
    "hatali_satir": hatali,
    "iptal_sayisi": iptal_sayisi,
    "toplam_tutar": round(toplam_tutar, 2),
    "aylik": dict(sorted(aylik.items())),
    "en_cok_harcayan": en_cok_harcayan,
}
with open("ozet.json", "w", encoding="utf-8") as f:
    json.dump(ozet, f, ensure_ascii=False, indent=2)

print(json.dumps(ozet, ensure_ascii=False, indent=2))
print("\n-- kontrol --")
for i, r in enumerate(tekil):
    print(i + 1, r["musteri"], r["tutar"], r["tarih"], r["durum"])

